// Assertiva OAuth2 — obter token
const CLIENT_ID = 'abc9cjvp39LjlSplYpK0eeZMSPi0Z8/mgDDbwsl2IbJ/t7kaG7sxSDT9ZLQQNbGUXkj9yIJVVc1hoPGkHp/0bg==';
const CLIENT_SECRET = 'xtV0v08ohSMtusYbhwjN4F4qL9dSloV44Tdhuz7fOiwr7nHTpOsiPOrjfEyXOJK5dnE+j5YMaEFnQrw+kRI8Sg==';
const BASE_URL = 'https://api.assertivasolucoes.com.br';

const body = $input.first().json.body || $input.first().json;
const action = body.action;
const cnpj = body.cnpj || '';
const cpf = body.cpf || '';
const phone = body.phone || '';
const protocolo = body.protocolo || '';

// Obter token OAuth2
const credentials = Buffer.from(`${CLIENT_ID}:${CLIENT_SECRET}`).toString('base64');
const tokenRes = await fetch(`${BASE_URL}/oauth2/v3/token`, {
  method: 'POST',
  headers: {
    'Authorization': `Basic ${credentials}`,
    'Content-Type': 'application/x-www-form-urlencoded',
  },
  body: 'grant_type=client_credentials',
});

if (!tokenRes.ok) {
  return [{ json: { error: `Auth failed: ${tokenRes.status}`, message: await tokenRes.text() } }];
}

const tokenData = await tokenRes.json();
const token = tokenData.access_token;

// Montar path baseado na acao
let path = '';
switch (action) {
  case 'lookup-cnpj':
    path = `/localize/v3/cnpj?cnpj=${cnpj}&idFinalidade=5`;
    break;
  case 'get-decision-makers':
    path = `/localize/v3/possiveis-decisores?cnpj=${cnpj}&idFinalidade=5${protocolo ? `&protocolo=${protocolo}` : ''}`;
    break;
  case 'lookup-cpf':
    path = `/localize/v3/cpf?cpf=${cpf}&idFinalidade=5`;
    break;
  case 'lookup-phone':
    path = `/localize/v3/telefone?telefone=${phone}&idFinalidade=5`;
    break;
  default:
    return [{ json: { error: 'Unknown action', message: `Action '${action}' not supported` } }];
}

// Chamar Assertiva
const res = await fetch(`${BASE_URL}${path}`, {
  headers: { 'Authorization': `Bearer ${token}` },
});

if (!res.ok) {
  const errBody = await res.text();
  return [{ json: { error: `Assertiva ${res.status}`, message: errBody } }];
}

const data = await res.json();
return [{ json: data }];
